          "notes": null
        },
        {
          "id": "0.2",
          "title": "Port saveDefinitionGrid to the main schema with all-or-nothing transactions",
          "status": "done",
          "notes": null
        },
        {
          "id": "0.3",
          "title": "Port and adapt unit and DB-backed tests for validation, duplicates, dimensions, and safety rules",
          "status": "done",
          "notes": null
        },
        {
          "id": "0.4",
          "title": "Create the admin definition catalog listing definition-only and published frequencies",
